const code = "\n    /* ==========================================================================\n       CANVAS & SYSTEM SETUP\n       ========================================================================== */\n    const canvas = document.getElementById('gameCanvas');\n    const ctx = canvas ? canvas.getContext('2d') : null;\n    let scaleFactor = 1.0;\n    let hoveredNodeId = null;\n\n    /* ==========================================================================\n       GLOBAL GAME VARIABLES & STATE\n       ========================================================================== */\n    let isGameRunning = false;\n    let timerInterval = null;\n    let currentLevelIndex = 0;\n    let currentLevelData = null;\n\n    const robotState = {\n      currentNodeId: 0,\n      prevNodeId: 0,\n      targetNodeId: null,\n      isMoving: false,\n      moveProgress: 0,\n      carryingFood: null,\n      bumpAnim: 0,\n      x: 0,\n      y: 0,\n      z: 0\n    };\n\n    \n    function computeCamera() {\n      // Refresh canvas scale and camera parameters\n      if (canvas) {\n        scaleFactor = Math.min((window.innerWidth || 800) / 800, (window.innerHeight || 600) / 600);\n      }\n    }\n\n    function resizeCanvas() {\n      if (!canvas) return;\n      const w = window.innerWidth || 800;\n      const h = window.innerHeight || 600;\n      canvas.width = w;\n      canvas.height = h;\n      scaleFactor = Math.min(w / 800, h / 600);\n      if (typeof computeCamera === 'function') computeCamera();\n    }\n    window.addEventListener('resize', resizeCanvas);\n    /* ==========================================================================\n       AUDIO SYNTHESIZER (Web Audio API)\n       ========================================================================== */\n    let audioCtx = null;\n    let audioMuted = false;\n\n    function initAudio() {\n      if (!audioCtx) {\n        audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n      }\n    }\n\n    function toggleAudio() {\n      audioMuted = !audioMuted;\n      document.getElementById('soundToggleBtn').innerText = audioMuted ? '\ud83d\udd07' : '\ud83d\udd0a';\n    }\n\n    function playSound(type) {\n      if (audioMuted) return;\n      initAudio();\n      if (!audioCtx) return;\n\n      const now = audioCtx.currentTime;\n      const osc = audioCtx.createOscillator();\n      const gain = audioCtx.createGain();\n      osc.connect(gain);\n      gain.connect(audioCtx.destination);\n\n      if (type === 'step') {\n        osc.type = 'sine';\n        osc.frequency.setValueAtTime(440, now);\n        osc.frequency.exponentialRampToValueAtTime(880, now + 0.05);\n        gain.gain.setValueAtTime(0.1, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.05);\n        osc.start(now);\n        osc.stop(now + 0.05);\n      } else if (type === 'pickup') {\n        osc.type = 'triangle';\n        osc.frequency.setValueAtTime(523.25, now);\n        osc.frequency.setValueAtTime(659.25, now + 0.08);\n        osc.frequency.setValueAtTime(783.99, now + 0.16);\n        gain.gain.setValueAtTime(0.2, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);\n        osc.start(now);\n        osc.stop(now + 0.3);\n      } else if (type === 'deliver') {\n        osc.type = 'sine';\n        osc.frequency.setValueAtTime(587.33, now);\n        osc.frequency.setValueAtTime(880.00, now + 0.1);\n        osc.frequency.setValueAtTime(1174.66, now + 0.2);\n        gain.gain.setValueAtTime(0.25, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.4);\n        osc.start(now);\n        osc.stop(now + 0.4);\n      } else if (type === 'bump') {\n        osc.type = 'sawtooth';\n        osc.frequency.setValueAtTime(200, now);\n        osc.frequency.exponentialRampToValueAtTime(70, now + 0.25);\n        gain.gain.setValueAtTime(0.3, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.25);\n        osc.start(now);\n        osc.stop(now + 0.25);\n      } else if (type === 'win') {\n        const notes = [523.25, 659.25, 783.99, 1046.50];\n        notes.forEach((freq, i) => {\n          const o = audioCtx.createOscillator();\n          const g = audioCtx.createGain();\n          o.connect(g);\n          g.connect(audioCtx.destination);\n          o.type = 'triangle';\n          o.frequency.setValueAtTime(freq, now + i * 0.12);\n          g.gain.setValueAtTime(0.25, now + i * 0.12);\n          g.gain.exponentialRampToValueAtTime(0.01, now + i * 0.12 + 0.25);\n          o.start(now + i * 0.12);\n          o.stop(now + i * 0.12 + 0.25);\n        });\n      } else if (type === 'lose') {\n        osc.type = 'sawtooth';\n        osc.frequency.setValueAtTime(280, now);\n        osc.frequency.exponentialRampToValueAtTime(90, now + 0.4);\n        gain.gain.setValueAtTime(0.3, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.4);\n        osc.start(now);\n        osc.stop(now + 0.4);\n      }\n    }\n\n    /* ==========================================================================\n       MAP DATA \u2014 LABIRIN MENARA ARSITEKTURAL\n       Platform = poligon kontinu (bukan blok grid). Dinding lavender naik dari\n       tepi setiap platform. Tangga asli 8-15 anak tangga. Jembatan lengkung biru,\n       taman & pohon, karakter kecil, dan collectible hadiah merah.\n       ========================================================================== */\n    const FOOD_TYPES = {\n      PIZZA: { name: 'Pizza', icon: '\ud83c\udf55' },\n      BURGER: { name: 'Burger', icon: '\ud83c\udf54' },\n      GIFT: { name: 'Hadiah', icon: '\ud83c\udf81' },\n      JUICE: { name: 'Jus Segar', icon: '\ud83e\udd64' },\n      BENTO: { name: 'Bento Box', icon: '\ud83c\udf71' },\n      CAKE: { name: 'Kue Manis', icon: '\ud83c\udf70' }\n    };\n\n    /* ------------------------------------------------------------------------\n       PLATFORM POLYGONS \u2014 koridor kontinu NARROW (lebar ~1.5-2 unit) + bentuk L\n       Level z=1..6. Dinding lavender TINGGI naik dari tepi tiap koridor.\n       ------------------------------------------------------------------------ */\n    const MAZE_PLATFORMS = [\n      /* ========== LEVEL 1 (z=1) \u2014 base lebar, labirin bawah ========== */\n      { z: 1, wall: 1.35, pts: [[0,0],[9,0],[9,1.5],[0,1.5]] },                    // koridor bawah-kiri\n      { z: 1, wall: 1.35, pts: [[9.5,0],[17,0],[17,1.5],[9.5,1.5]] },              // koridor bawah-kanan\n      { z: 1, wall: 1.25, pts: [[1,2],[3,2],[3,4],[1,4]] },                        // blok kiri\n      { z: 1, wall: 1.45, pts: [[5,2],[6.5,2],[6.5,4],[5,4]] },                    // blok kecil\n      { z: 1, wall: 1.35, pts: [[11,2],[13,2],[13,4],[11,4]] },                    // blok kanan\n      { z: 1, wall: 1.25, pts: [[15,2],[16.5,2],[16.5,4],[15,4]] },                // blok kanan kecil\n      { z: 1, wall: 1.35, pts: [[1,5],[4,5],[4,7],[1,7]] },                        // koridor L kiri\n      { z: 1, wall: 1.45, pts: [[5.5,5],[8,5],[8,7],[5.5,7]] },                    // koridor tengah\n      { z: 1, wall: 1.25, pts: [[9.5,5],[12,5],[12,7],[9.5,7]] },                  // koridor tengah-kanan\n      { z: 1, wall: 1.35, pts: [[13.5,5],[16.5,5],[16.5,7],[13.5,7]] },            // koridor kanan\n      { z: 1, wall: 1.35, pts: [[0,8.5],[2,8.5],[2,10.5],[0,10.5]] },              // blok kiri-bawah\n      { z: 1, wall: 1.25, pts: [[4,8.5],[6.5,8.5],[6.5,10.5],[4,10.5]] },          // blok tengah\n      { z: 1, wall: 1.45, pts: [[8,8.5],[10,8.5],[10,10.5],[8,10.5]] },            // blok tengah\n      { z: 1, wall: 1.35, pts: [[12,8.5],[14,8.5],[14,10.5],[12,10.5]] },          // blok kanan\n      { z: 1, wall: 1.25, pts: [[1,11.5],[3.5,11.5],[3.5,13],[1,13]] },            // blok terpisah kiri-bawah\n      { z: 1, wall: 1.35, pts: [[9,11.5],[12,11.5],[12,13],[9,13]] },              // blok terpisah tengah-bawah\n      { z: 1, wall: 1.45, pts: [[14,11.5],[16.5,11.5],[16.5,13],[14,13]] },        // blok terpisah kanan-bawah\n\n      /* ========== LEVEL 2 (z=2) \u2014 koridor offset ========== */\n      { z: 2, wall: 1.35, pts: [[2,1],[5,1],[5,3],[2,3]] },                        // koridor kiri\n      { z: 2, wall: 1.25, pts: [[7,1],[10,1],[10,3],[7,3]] },                      // koridor tengah-kiri\n      { z: 2, wall: 1.35, pts: [[12,1],[15,1],[15,3],[12,3]] },                    // koridor kanan\n      { z: 2, wall: 1.45, pts: [[3,4.5],[6,4.5],[6,6.5],[3,6.5]] },                // L tengah\n      { z: 2, wall: 1.25, pts: [[8,4.5],[11,4.5],[11,6.5],[8,6.5]] },              // koridor\n      { z: 2, wall: 1.35, pts: [[13,4.5],[16,4.5],[16,6.5],[13,6.5]] },            // koridor kanan\n      { z: 2, wall: 1.35, pts: [[2,8],[4,8],[4,10],[2,10]] },                      // blok kiri\n      { z: 2, wall: 1.25, pts: [[6,8],[8.5,8],[8.5,10],[6,10]] },                  // blok tengah\n      { z: 2, wall: 1.45, pts: [[11,8],[14,8],[14,10],[11,10]] },                  // blok kanan\n      { z: 2, wall: 1.35, pts: [[5,11],[7.5,11],[7.5,12.5],[5,12.5]] },            // blok bawah\n\n      /* ========== LEVEL 3 (z=3) \u2014 koridor berkelok ========== */\n      { z: 3, wall: 1.35, pts: [[1,2],[4,2],[4,4],[1,4]] },                        // koridor kiri\n      { z: 3, wall: 1.45, pts: [[6,2],[8,2],[8,4],[6,4]] },                        // blok\n      { z: 3, wall: 1.25, pts: [[10,2],[13,2],[13,4],[10,4]] },                    // koridor\n      { z: 3, wall: 1.35, pts: [[15,2],[16.5,2],[16.5,4],[15,4]] },                // blok kanan\n      { z: 3, wall: 1.35, pts: [[2,5.5],[5,5.5],[5,7.5],[2,7.5]] },                // L kiri\n      { z: 3, wall: 1.25, pts: [[7,5.5],[10,5.5],[10,7.5],[7,7.5]] },              // koridor tengah\n      { z: 3, wall: 1.45, pts: [[12,5.5],[15,5.5],[15,7.5],[12,7.5]] },            // koridor kanan\n      { z: 3, wall: 1.35, pts: [[1,9],[3.5,9],[3.5,11],[1,11]] },                  // blok kiri\n      { z: 3, wall: 1.25, pts: [[6,9],[9,9],[9,11],[6,11]] },                      // blok tengah\n      { z: 3, wall: 1.35, pts: [[11,9],[13.5,9],[13.5,11],[11,11]] },              // blok kanan\n      { z: 3, wall: 1.45, pts: [[4,12],[6.5,12],[6.5,13.5],[4,13.5]] },            // blok bawah\n\n      /* ========== LEVEL 4 (z=4) \u2014 koridor sempit ========== */\n      { z: 4, wall: 1.45, pts: [[2,2.5],[5,2.5],[5,4.5],[2,4.5]] },                // koridor kiri\n      { z: 4, wall: 1.25, pts: [[7,2.5],[10,2.5],[10,4.5],[7,4.5]] },              // koridor\n      { z: 4, wall: 1.35, pts: [[12,2.5],[15,2.5],[15,4.5],[12,4.5]] },            // koridor kanan\n      { z: 4, wall: 1.35, pts: [[3,6],[6,6],[6,8],[3,8]] },                        // L tengah\n      { z: 4, wall: 1.45, pts: [[8,6],[11,6],[11,8],[8,8]] },                      // koridor\n      { z: 4, wall: 1.25, pts: [[13,6],[16,6],[16,8],[13,8]] },                    // koridor kanan\n      { z: 4, wall: 1.35, pts: [[2,9.5],[4.5,9.5],[4.5,11.5],[2,11.5]] },          // blok kiri\n      { z: 4, wall: 1.45, pts: [[7,9.5],[10,9.5],[10,11.5],[7,11.5]] },            // blok tengah\n      { z: 4, wall: 1.35, pts: [[12,9.5],[15,9.5],[15,11.5],[12,11.5]] },          // blok kanan\n\n      /* ========== LEVEL 5 (z=5) \u2014 koridor atas ========== */\n      { z: 5, wall: 1.45, pts: [[3,3],[6,3],[6,5],[3,5]] },                        // koridor kiri\n      { z: 5, wall: 1.35, pts: [[8,3],[11,3],[11,5],[8,5]] },                      // koridor tengah\n      { z: 5, wall: 1.35, pts: [[13,3],[16,3],[16,5],[13,5]] },                    // koridor kanan\n      { z: 5, wall: 1.35, pts: [[4,6.5],[7,6.5],[7,8.5],[4,8.5]] },                // L tengah-kiri\n      { z: 5, wall: 1.45, pts: [[9,6.5],[12,6.5],[12,8.5],[9,8.5]] },              // koridor tengah\n      { z: 5, wall: 1.25, pts: [[14,6.5],[16,6.5],[16,8.5],[14,8.5]] },            // koridor kanan\n      { z: 5, wall: 1.35, pts: [[5,10],[8,10],[8,12],[5,12]] },                    // blok bawah\n\n      /* ========== LEVEL 6 (z=6) \u2014 puncak ========== */\n      { z: 6, wall: 1.45, pts: [[5,4.5],[8,4.5],[8,6.5],[5,6.5]] },                // puncak kiri\n      { z: 6, wall: 1.35, pts: [[10,4.5],[13,4.5],[13,6.5],[10,6.5]] },            // puncak kanan\n      { z: 6, wall: 1.45, pts: [[7,2],[9,2],[9,3.5],[7,3.5]] },                    // puncak tengah\n      { z: 6, wall: 1.35, pts: [[8,8],[10,8],[10,9.5],[8,9.5]] }                   // puncak kecil\n    ];\n\n    /* ------------------------------------------------------------------------\n       TANGGA (staircases) \u2014 tiap tangga = 8-15 anak tangga naik dari (x1,y1,z1)\n       ke (x2,y2,z2). Menghubungkan dua level platform.\n       ------------------------------------------------------------------------ */\n    const MAZE_STAIRS = [\n      /* z1 -> z2 */\n      { x1: 3, y1: 6, z1: 1, x2: 3.5, y2: 5, z2: 2, n: 9 },\n      { x1: 8, y1: 6, z1: 1, x2: 8.5, y2: 5.3, z2: 2, n: 9 },\n      { x1: 14, y1: 6, z1: 1, x2: 14, y2: 5.5, z2: 2, n: 9 },\n      { x1: 3, y1: 3, z1: 1, x2: 3, y2: 2, z2: 2, n: 8 },\n      { x1: 12, y1: 3, z1: 1, x2: 12, y2: 2, z2: 2, n: 8 },\n      { x1: 10, y1: 9.5, z1: 1, x2: 10, y2: 9, z2: 2, n: 8 },\n      { x1: 2, y1: 9.5, z1: 1, x2: 2, y2: 9, z2: 2, n: 8 },\n      { x1: 14, y1: 9.5, z1: 1, x2: 14, y2: 9, z2: 2, n: 8 },\n      /* z2 -> z3 */\n      { x1: 3, y1: 2, z1: 2, x2: 3, y2: 3, z2: 3, n: 8 },\n      { x1: 8, y1: 2, z1: 2, x2: 8, y2: 3, z2: 3, n: 8 },\n      { x1: 12, y1: 2, z1: 2, x2: 12, y2: 3, z2: 3, n: 8 },\n      { x1: 4, y1: 6, z1: 2, x2: 4, y2: 7, z2: 3, n: 9 },\n      { x1: 9, y1: 6, z1: 2, x2: 9, y2: 7, z2: 3, n: 9 },\n      { x1: 14, y1: 6, z1: 2, x2: 14, y2: 7, z2: 3, n: 9 },\n      { x1: 3, y1: 9, z1: 2, x2: 3, y2: 10, z2: 3, n: 8 },\n      { x1: 7, y1: 9, z1: 2, x2: 7, y2: 10, z2: 3, n: 8 },\n      { x1: 12, y1: 9, z1: 2, x2: 12, y2: 10, z2: 3, n: 8 },\n      /* z3 -> z4 */\n      { x1: 3, y1: 3, z1: 3, x2: 3, y2: 3.5, z2: 4, n: 8 },\n      { x1: 8, y1: 3, z1: 3, x2: 8, y2: 3.5, z2: 4, n: 8 },\n      { x1: 13, y1: 3, z1: 3, x2: 13, y2: 3.5, z2: 4, n: 8 },\n      { x1: 4, y1: 6.5, z1: 3, x2: 4.5, y2: 7, z2: 4, n: 9 },\n      { x1: 9, y1: 6.5, z1: 3, x2: 9.5, y2: 7, z2: 4, n: 9 },\n      { x1: 14, y1: 6.5, z1: 3, x2: 14.5, y2: 7, z2: 4, n: 9 },\n      { x1: 3, y1: 10, z1: 3, x2: 3.5, y2: 10.5, z2: 4, n: 8 },\n      { x1: 8, y1: 10, z1: 3, x2: 8.5, y2: 10.5, z2: 4, n: 8 },\n      { x1: 13, y1: 10, z1: 3, x2: 13.5, y2: 10.5, z2: 4, n: 8 },\n      /* z4 -> z5 */\n      { x1: 4, y1: 3.5, z1: 4, x2: 4.5, y2: 4, z2: 5, n: 8 },\n      { x1: 9, y1: 3.5, z1: 4, x2: 9.5, y2: 4, z2: 5, n: 8 },\n      { x1: 14, y1: 3.5, z1: 4, x2: 14.5, y2: 4, z2: 5, n: 8 },\n      { x1: 5, y1: 7, z1: 4, x2: 5.5, y2: 7.5, z2: 5, n: 9 },\n      { x1: 10, y1: 7, z1: 4, x2: 10.5, y2: 7.5, z2: 5, n: 9 },\n      { x1: 15, y1: 7, z1: 4, x2: 15, y2: 7.5, z2: 5, n: 9 },\n      { x1: 4.5, y1: 10.5, z1: 4, x2: 5, y2: 11, z2: 5, n: 8 },\n      /* z5 -> z6 */\n      { x1: 5, y1: 4.5, z1: 5, x2: 5.5, y2: 5, z2: 6, n: 8 },\n      { x1: 10, y1: 4.5, z1: 5, x2: 10, y2: 5, z2: 6, n: 8 },\n      { x1: 6, y1: 7, z1: 5, x2: 6, y2: 6, z2: 6, n: 8 },\n      { x1: 9, y1: 7.5, z1: 5, x2: 9, y2: 8.5, z2: 6, n: 8 }\n    ];\n\n    /* ------------------------------------------------------------------------\n       JEMBATAN LENGKUNG BIRU (kecil, tipis) \u2014 menghubungkan dua bagian platform\n       ------------------------------------------------------------------------ */\n    const MAZE_BRIDGES = [\n      { x1: 4.3, y1: 6, x2: 5.2, y2: 6, z: 1 },\n      { x1: 8.3, y1: 6, x2: 9.2, y2: 6, z: 1 },\n      { x1: 12.3, y1: 6, x2: 13.2, y2: 6, z: 1 },\n      { x1: 6.3, y1: 5.5, x2: 7.7, y2: 5.5, z: 2 },\n      { x1: 8.8, y1: 5.5, x2: 10.7, y2: 5.5, z: 2 },\n      { x1: 5.3, y1: 6.5, x2: 6.7, y2: 6.5, z: 3 },\n      { x1: 10.3, y1: 6.5, x2: 11.7, y2: 6.5, z: 3 },\n      { x1: 6.3, y1: 7, x2: 7.7, y2: 7, z: 4 },\n      { x1: 11.3, y1: 7, x2: 12.7, y2: 7, z: 4 },\n      { x1: 7.3, y1: 7.5, x2: 8.7, y2: 7.5, z: 5 },\n      { x1: 8.3, y1: 5.5, x2: 9.7, y2: 5.5, z: 6 }\n    ];\n\n    /* ------------------------------------------------------------------------\n       TAMAN (green garden patches) \u2014 ditanam di platform lebar\n       ------------------------------------------------------------------------ */\n    const MAZE_GARDENS = [\n      { x: 2, y: 0.8, z: 1, n: 5, w: 2.6, h: 1.2 },   // lower-left\n      { x: 10, y: 0.8, z: 1, n: 5, w: 2.4, h: 1.2 },  // lower-middle\n      { x: 15, y: 0.8, z: 1, n: 4, w: 1.6, h: 1.2 },  // lower-right\n      { x: 6, y: 6, z: 1, n: 5, w: 1.8, h: 1.4 },     // middle-center\n      { x: 12.5, y: 9.5, z: 1, n: 4, w: 1.6, h: 1.4 },// middle-right\n      { x: 4.5, y: 5.5, z: 2, n: 4, w: 1.6, h: 1.4 }, // middle-left\n      { x: 9, y: 5.5, z: 2, n: 4, w: 1.6, h: 1.4 },   // middle-center\n      { x: 14, y: 5.5, z: 2, n: 4, w: 1.6, h: 1.4 },  // middle-right\n      { x: 9, y: 7, z: 4, n: 5, w: 1.8, h: 1.4 },     // upper-middle\n      { x: 6, y: 7.5, z: 5, n: 4, w: 1.6, h: 1.4 }    // upper-left\n    ];\n\n    /* ------------------------------------------------------------------------\n       KARAKTER KECIL (mini characters)\n       ------------------------------------------------------------------------ */\n    const MAZE_CHARACTERS = [\n      { x: 0.5, y: 1, z: 1 },    { x: 8, y: 1, z: 1 },\n      { x: 16, y: 1, z: 1 },     { x: 2.7, y: 3, z: 1 },\n      { x: 6, y: 3, z: 1 },      { x: 12, y: 3, z: 1 },\n      { x: 15.5, y: 3, z: 1 },   { x: 3, y: 6, z: 1 },\n      { x: 7, y: 6, z: 1 },      { x: 11, y: 6, z: 1 },\n      { x: 15, y: 6, z: 1 },     { x: 1, y: 9.5, z: 1 },\n      { x: 5, y: 9.5, z: 1 },    { x: 9, y: 9.5, z: 1 },\n      { x: 13, y: 9.5, z: 1 },   { x: 10, y: 12, z: 1 },\n      { x: 2.5, y: 12, z: 1 },   { x: 15, y: 12, z: 1 },\n      { x: 3, y: 2, z: 2 },      { x: 9, y: 2, z: 2 },\n      { x: 13, y: 2, z: 2 },     { x: 4, y: 5.5, z: 2 },\n      { x: 9, y: 5.5, z: 2 },    { x: 14, y: 5.5, z: 2 },\n      { x: 3, y: 9, z: 2 },      { x: 7, y: 9, z: 2 },\n      { x: 12, y: 9, z: 2 },     { x: 2, y: 3, z: 3 },\n      { x: 7.7, y: 3, z: 3 },      { x: 12, y: 3, z: 3 },\n      { x: 4, y: 6.5, z: 3 },    { x: 9, y: 6.5, z: 3 },\n      { x: 14, y: 6.5, z: 3 },   { x: 3, y: 10, z: 3 },\n      { x: 8, y: 10, z: 3 },     { x: 12, y: 10, z: 3 },\n      { x: 4, y: 3.5, z: 4 },    { x: 9, y: 3.5, z: 4 },\n      { x: 14, y: 3.5, z: 4 },   { x: 5, y: 7, z: 4 },\n      { x: 10, y: 7, z: 4 },     { x: 15, y: 7, z: 4 },\n      { x: 3, y: 10.5, z: 4 },   { x: 8, y: 10.5, z: 4 },\n      { x: 13, y: 10.5, z: 4 },  { x: 4, y: 4, z: 5 },\n      { x: 9, y: 4, z: 5 },      { x: 14, y: 4, z: 5 },\n      { x: 5, y: 7.5, z: 5 },    { x: 10, y: 7.5, z: 5 },\n      { x: 15, y: 7.5, z: 5 },   { x: 6, y: 11, z: 5 },\n      { x: 6, y: 5.5, z: 6 },    { x: 11, y: 5.5, z: 6 },\n      { x: 8, y: 2.8, z: 6 },    { x: 9, y: 8.8, z: 6 }\n    ];\n\n    /* ------------------------------------------------------------------------\n       COLLECTIBLES \u2014 hadiah merah kecil\n       ------------------------------------------------------------------------ */\n    const MAZE_COLLECTIBLES = [\n      { x: 6.5, y: 5, z: 6 },\n      { x: 11.5, y: 5, z: 6 },\n      { x: 7, y: 3, z: 6 },\n      { x: 8.5, y: 8.5, z: 6 },\n      { x: 6, y: 10.5, z: 5 },\n      { x: 6, y: 11, z: 5 },\n      { x: 14.5, y: 4, z: 4 },\n      { x: 2.5, y: 4, z: 4 },\n      { x: 13, y: 6, z: 3 },\n      { x: 3, y: 7, z: 3 },\n      { x: 10.5, y: 6, z: 2 },\n      { x: 3, y: 9.5, z: 2 },\n      { x: 11, y: 12, z: 1 },\n      { x: 3, y: 12, z: 1 },\n      { x: 16, y: 6, z: 1 }\n    ];\n\n    /* ==========================================================================\n       LEVEL DEFINITIONS (map-aligned node & edge positions for maps_robo-delivery2.png)\n       ========================================================================== */\n    const MAP_NODES_BASE = [\n      { id: 0, x: 20.5, y: 22 }, // Top-Left Start / Food Platform\n      { id: 1, x: 35, y: 27 },   // Upper Landing 1\n      { id: 2, x: 52, y: 34 },   // Center High Bridge\n      { id: 3, x: 62, y: 20 },   // Upper Landing 2\n      { id: 4, x: 84, y: 10 },   // Top-Right Peak Customer 1\n      { id: 5, x: 33, y: 43 },   // Mid-Left Terrace Food 2\n      { id: 6, x: 50, y: 52 },   // Center Low Platform\n      { id: 7, x: 73, y: 36 },   // Mid-Right Terrace Customer 2\n      { id: 8, x: 18, y: 78 },   // Lower-Left Gift Platform\n      { id: 9, x: 48, y: 78 },   // Lower-Center Terrace\n      { id: 10, x: 75, y: 84 }    // Lower-Right Customer 3\n    ];\n\n    const MAP_EDGES_BASE = [\n      [0, 1], [1, 2], [2, 3], [3, 4],\n      [1, 5], [5, 6], [6, 7],\n      [5, 8], [8, 9], [9, 10],\n      [6, 9]\n    ];\n\n    const LEVELS = [\n      {\n        id: 1,\n        title: \"Taman Kota\",\n        timeLimit: 180,\n        rewardCoins: 350,\n        nodes: MAP_NODES_BASE,\n        edges: MAP_EDGES_BASE,\n        startNode: 0,\n        foodStations: [\n          { nodeId: 0, food: FOOD_TYPES.PIZZA }\n        ],\n        customers: [\n          { id: 'c1', nodeId: 4, wantsFood: FOOD_TYPES.PIZZA, delivered: false, gender: 'female' }\n        ],\n        obstacles: [\n          { id: 'obs1', path: [1, 2, 3], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.015, icon: '\ud83d\udeb6\u200d\u2642\ufe0f' }\n        ]\n      },\n      {\n        id: 2,\n        title: \"Pusat Kota\",\n        timeLimit: 240,\n        rewardCoins: 450,\n        nodes: MAP_NODES_BASE,\n        edges: MAP_EDGES_BASE,\n        startNode: 0,\n        foodStations: [\n          { nodeId: 0, food: FOOD_TYPES.PIZZA },\n          { nodeId: 5, food: FOOD_TYPES.BURGER }\n        ],\n        customers: [\n          { id: 'c1', nodeId: 4, wantsFood: FOOD_TYPES.PIZZA, delivered: false, gender: 'female' },\n          { id: 'c2', nodeId: 7, wantsFood: FOOD_TYPES.BURGER, delivered: false, gender: 'male' }\n        ],\n        obstacles: [\n          { id: 'obs1', path: [1, 2, 3], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.015, icon: '\ud83d\udeb6\u200d\u2642\ufe0f' },\n          { id: 'obs2', path: [5, 6, 7], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.016, icon: '\ud83d\udeb6\u200d\u2640\ufe0f' }\n        ]\n      },\n      {\n        id: 3,\n        title: \"Pasar Malam\",\n        timeLimit: 300,\n        rewardCoins: 550,\n        nodes: MAP_NODES_BASE,\n        edges: MAP_EDGES_BASE,\n        startNode: 0,\n        foodStations: [\n          { nodeId: 0, food: FOOD_TYPES.PIZZA },\n          { nodeId: 5, food: FOOD_TYPES.BURGER },\n          { nodeId: 8, food: FOOD_TYPES.GIFT }\n        ],\n        customers: [\n          { id: 'c1', nodeId: 4, wantsFood: FOOD_TYPES.PIZZA, delivered: false, gender: 'female' },\n          { id: 'c2', nodeId: 7, wantsFood: FOOD_TYPES.BURGER, delivered: false, gender: 'male' },\n          { id: 'c3', nodeId: 10, wantsFood: FOOD_TYPES.GIFT, delivered: false, gender: 'female' }\n        ],\n        obstacles: [\n          { id: 'obs1', path: [1, 2, 3], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.016, icon: '\ud83d\udeb6\u200d\u2642\ufe0f' },\n          { id: 'obs2', path: [5, 6, 7], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.017, icon: '\ud83d\udeb6\u200d\u2640\ufe0f' },\n          { id: 'obs3', path: [8, 9, 10], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.015, icon: '\ud83d\udef8' }\n        ]\n      },\n      {\n        id: 4,\n        title: \"Metropolis High\",\n        timeLimit: 320,\n        rewardCoins: 650,\n        nodes: MAP_NODES_BASE,\n        edges: MAP_EDGES_BASE,\n        startNode: 0,\n        foodStations: [\n          { nodeId: 0, food: FOOD_TYPES.PIZZA },\n          { nodeId: 5, food: FOOD_TYPES.JUICE },\n          { nodeId: 8, food: FOOD_TYPES.CAKE }\n        ],\n        customers: [\n          { id: 'c1', nodeId: 4, wantsFood: FOOD_TYPES.PIZZA, delivered: false, gender: 'female' },\n          { id: 'c2', nodeId: 7, wantsFood: FOOD_TYPES.JUICE, delivered: false, gender: 'male' },\n          { id: 'c3', nodeId: 10, wantsFood: FOOD_TYPES.CAKE, delivered: false, gender: 'female' }\n        ],\n        obstacles: [\n          { id: 'obs1', path: [1, 2, 3], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.018, icon: '\ud83d\udeb6\u200d\u2642\ufe0f' },\n          { id: 'obs2', path: [5, 6, 7], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.018, icon: '\ud83e\uddf9' },\n          { id: 'obs3', path: [8, 9, 10], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.017, icon: '\ud83d\udea7' }\n        ]\n      },\n      {\n        id: 5,\n        title: \"Grand Citadel\",\n        timeLimit: 360,\n        rewardCoins: 800,\n        nodes: MAP_NODES_BASE,\n        edges: MAP_EDGES_BASE,\n        startNode: 0,\n        foodStations: [\n          { nodeId: 0, food: FOOD_TYPES.PIZZA },\n          { nodeId: 5, food: FOOD_TYPES.BURGER },\n          { nodeId: 8, food: FOOD_TYPES.GIFT }\n        ],\n        customers: [\n          { id: 'c1', nodeId: 4, wantsFood: FOOD_TYPES.PIZZA, delivered: false, gender: 'female' },\n          { id: 'c2', nodeId: 7, wantsFood: FOOD_TYPES.BURGER, delivered: false, gender: 'male' },\n          { id: 'c3', nodeId: 10, wantsFood: FOOD_TYPES.GIFT, delivered: false, gender: 'female' }\n        ],\n        obstacles: [\n          { id: 'obs1', path: [0, 1, 2, 3, 4], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.020, icon: '\ud83d\udeb6\u200d\u2642\ufe0f' },\n          { id: 'obs2', path: [1, 5, 6, 7], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.020, icon: '\ud83d\udeb6\u200d\u2640\ufe0f' },\n          { id: 'obs3', path: [5, 8, 9, 10], currentIndex: 0, targetIndex: 1, t: 0, speed: 0.019, icon: '\ud83e\uddf9' }\n        ]\n      }\n    ];\n\n    \n        /* ==========================================================================\n       MAP BACKGROUND IMAGE & BULLETPROOF PROJECTION ENGINE\n       ========================================================================== */\n        const mapBgImg = new Image();\n    let mapBgLoaded = false;\n    mapBgImg.onload = () => {\n      mapBgLoaded = true;\n      if (typeof computeCamera === 'function') computeCamera();\n    };\n    mapBgImg.onerror = () => {\n      console.warn('Map background image load error, trying fallbacks...');\n      const fallbacks = [\n        'maps_robo-delivery2.png',\n        '/web-games/robo-delivery/maps_robo-delivery2.png',\n        '/robo-delivery/maps_robo-delivery2.png',\n        './maps_robo-delivery2.png'\n      ];\n      for (const src of fallbacks) {\n        if (mapBgImg.src.indexOf(src) === -1) {\n          mapBgImg.src = src;\n          break;\n        }\n      }\n    };\n    mapBgImg.src = 'maps_robo-delivery2.png';\n\n    function getMapBounds() {\n      const imgAspect = (mapBgImg && mapBgImg.width && mapBgImg.height) ? (mapBgImg.width / mapBgImg.height) : 1.0;\n      const canvasAspect = canvas.width / canvas.height;\n\n      let dw, dh, dx, dy;\n      if (canvasAspect > imgAspect) {\n        dh = canvas.height * 0.94;\n        dw = dh * imgAspect;\n      } else {\n        dw = canvas.width * 0.94;\n        dh = dw / imgAspect;\n      }\n      dx = (canvas.width - dw) / 2;\n      dy = (canvas.height - dh) / 2 - 10;\n\n      return { dx, dy, dw, dh };\n    }\n\n    function proj(x, y, z = 0) {\n      const b = getMapBounds();\n      return {\n        x: b.dx + (x / 100.0) * b.dw,\n        y: b.dy + (y / 100.0) * b.dh\n      };\n    }\n\n    /* ==========================================================================\n       GAME LOAD & HUD UPDATES\n       ========================================================================== */\n    function loadLevel(levelIndex) {\n      currentLevelIndex = levelIndex;\n      currentLevelData = JSON.parse(JSON.stringify(LEVELS[levelIndex]));\n\n      robotState.currentNodeId = currentLevelData.startNode;\n      robotState.prevNodeId = currentLevelData.startNode;\n      robotState.targetNodeId = null;\n      robotState.isMoving = false;\n      robotState.moveProgress = 0;\n      robotState.carryingFood = null;\n      robotState.bumpAnim = 0;\n\n      const startNode = currentLevelData.nodes.find(n => n.id === currentLevelData.startNode);\n      const startPos = proj(startNode.x, startNode.y, startNode.z);\n      robotState.x = startPos.x;\n      robotState.y = startPos.y;\n      robotState.z = startNode.z;\n\n      timerSeconds = currentLevelData.timeLimit;\n      deliveredCount = 0;\n      totalCustomers = currentLevelData.customers.length;\n\n      computeCamera();\n      updateHUD();\n      updateCarryingHUD();\n    }\n\n    function updateHUD() {\n      const m = Math.floor(timerSeconds / 60);\n      const s = timerSeconds % 60;\n      document.getElementById('timerVal').innerText = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;\n      document.getElementById('levelVal').innerText = `Level ${currentLevelData.id}`;\n    }\n\n    function updateCarryingHUD() {\n      const iconEl = document.getElementById('carryingIcon');\n      const textEl = document.getElementById('carryingText');\n\n      if (robotState.carryingFood) {\n        iconEl.innerText = robotState.carryingFood.icon;\n        textEl.innerText = `Membawa ${robotState.carryingFood.name}`;\n      } else {\n        iconEl.innerText = '\ud83e\udd16';\n        textEl.innerText = 'Tangan Kosong';\n      }\n    }\n\n    function startTimer() {\n      if (timerInterval) clearInterval(timerInterval);\n      timerInterval = setInterval(() => {\n        if (!isGameRunning) return;\n        timerSeconds--;\n        updateHUD();\n\n        if (timerSeconds <= 0) {\n          clearInterval(timerInterval);\n          gameLose();\n        }\n      }, 1000);\n    }\n\n    function startGame() {\n      initAudio();\n      document.getElementById('screenTitle').classList.add('hidden');\n      document.getElementById('screenLevelSelect').classList.add('hidden');\n      document.getElementById('screenWin').classList.add('hidden');\n      document.getElementById('screenLose').classList.add('hidden');\n\n      loadLevel(currentLevelIndex);\n      isGameRunning = true;\n      startTimer();\n    }\n\n    function showTitleScreen() {\n      isGameRunning = false;\n      if (timerInterval) clearInterval(timerInterval);\n      document.getElementById('screenTitle').classList.remove('hidden');\n      document.getElementById('screenLevelSelect').classList.add('hidden');\n      document.getElementById('screenWin').classList.add('hidden');\n      document.getElementById('screenLose').classList.add('hidden');\n    }\n\n    function showLevelSelect() {\n      const container = document.getElementById('levelGridContainer');\n      container.innerHTML = '';\n\n      LEVELS.forEach((lvl, idx) => {\n        const isUnlocked = unlockedLevels.includes(lvl.id);\n        const isActive = idx === currentLevelIndex;\n\n        const btn = document.createElement('button');\n        btn.className = `level-btn ${isUnlocked ? '' : 'locked'} ${isActive ? 'active' : ''}`;\n        btn.innerText = `Level ${lvl.id}`;\n        \n        if (isUnlocked) {\n          btn.onclick = () => {\n            currentLevelIndex = idx;\n            hideLevelSelect();\n            startGame();\n          };\n        }\n        container.appendChild(btn);\n      });\n\n      document.getElementById('screenLevelSelect').classList.remove('hidden');\n    }\n\n    function hideLevelSelect() {\n      document.getElementById('screenLevelSelect').classList.add('hidden');\n    }\n\n    function showSettingsModal() {\n      alert(\"Pengaturan Audio & Tampilan Map Robo Delivery.\");\n    }\n\n    function nextLevel() {\n      if (currentLevelIndex < LEVELS.length - 1) {\n        currentLevelIndex++;\n        if (!unlockedLevels.includes(LEVELS[currentLevelIndex].id)) {\n          unlockedLevels.push(LEVELS[currentLevelIndex].id);\n        }\n        startGame();\n      } else {\n        showTitleScreen();\n      }\n    }\n\n    function retryLevel() {\n      startGame();\n    }\n\n    function gameWin() {\n      isGameRunning = false;\n      if (timerInterval) clearInterval(timerInterval);\n      playSound('win');\n\n      if (currentLevelIndex < LEVELS.length - 1) {\n        const nextLvlId = LEVELS[currentLevelIndex + 1].id;\n        if (!unlockedLevels.includes(nextLvlId)) {\n          unlockedLevels.push(nextLvlId);\n        }\n      }\n\n      document.getElementById('rewardCoinsVal').innerText = `+${currentLevelData.rewardCoins}`;\n      document.getElementById('screenWin').classList.remove('hidden');\n\n      try {\n        const msg = {\n          type: 'GAME_COMPLETE',\n          gameId: 'robo-delivery',\n          title: 'Robo Delivery',\n          category: 'kognitif',\n          level: currentLevelData.id || 1,\n          score: 100,\n          xp: 120,\n          coins: currentLevelData.rewardCoins || 50,\n          duration: 60,\n          completed: true\n        };\n        if (window.ReactNativeWebView && window.ReactNativeWebView.postMessage) {\n          window.ReactNativeWebView.postMessage(JSON.stringify(msg));\n        }\n        if (window.parent && window.parent !== window) {\n          window.parent.postMessage(msg, '*');\n        }\n      } catch (e) {\n        console.log('Post message error:', e);\n      }\n    }\n\n    function gameLose() {\n      isGameRunning = false;\n      if (timerInterval) clearInterval(timerInterval);\n      playSound('lose');\n      document.getElementById('screenLose').classList.remove('hidden');\n    }\n\n    /* ==========================================================================\n       MOVEMENT & PATHFINDING\n       ========================================================================== */\n    function isEdgeConnected(fromId, toId) {\n      if (!currentLevelData) return false;\n      return currentLevelData.edges.some(e => \n        (e[0] === fromId && e[1] === toId) || (e[1] === fromId && e[0] === toId)\n      );\n    }\n\n    function moveToNode(targetId) {\n      if (!isGameRunning || robotState.isMoving) return;\n      if (!isEdgeConnected(robotState.currentNodeId, targetId)) return;\n\n      robotState.prevNodeId = robotState.currentNodeId;\n      robotState.targetNodeId = targetId;\n      robotState.isMoving = true;\n      robotState.moveProgress = 0;\n      playSound('step');\n    }\n\n    function checkObstacleCollisions() {\n      if (!isGameRunning || !currentLevelData) return;\n\n      const playerPosNode = robotState.isMoving ? robotState.targetNodeId : robotState.currentNodeId;\n\n      currentLevelData.obstacles.forEach(obs => {\n        const obsCurrNode = obs.path[obs.currentIndex];\n        const obsTargetNode = obs.path[obs.targetIndex];\n\n        if (playerPosNode === obsCurrNode || (robotState.isMoving && playerPosNode === obsTargetNode && obs.t > 0.4)) {\n          playSound('bump');\n          robotState.bumpAnim = 20;\n\n          if (robotState.isMoving) {\n            robotState.targetNodeId = robotState.prevNodeId;\n            robotState.moveProgress = 0;\n          } else {\n            robotState.currentNodeId = robotState.prevNodeId;\n            const prevN = currentLevelData.nodes.find(n => n.id === robotState.prevNodeId);\n            const pos = proj(prevN.x, prevN.y, prevN.z);\n            robotState.x = pos.x;\n            robotState.y = pos.y;\n            robotState.z = prevN.z;\n          }\n        }\n      });\n    }\n\n    function updateObstacles() {\n      if (!isGameRunning || !currentLevelData) return;\n\n      currentLevelData.obstacles.forEach(obs => {\n        obs.t += obs.speed;\n        if (obs.t >= 1) {\n          obs.t = 0;\n          obs.currentIndex = obs.targetIndex;\n          obs.targetIndex = (obs.targetIndex + 1) % obs.path.length;\n        }\n      });\n    }\n\n    function updateRobot() {\n      if (!robotState.isMoving || !currentLevelData) return;\n\n      robotState.moveProgress += 0.05;\n      const fromNode = currentLevelData.nodes.find(n => n.id === robotState.currentNodeId);\n      const toNode = currentLevelData.nodes.find(n => n.id === robotState.targetNodeId);\n\n      const p1 = proj(fromNode.x, fromNode.y, fromNode.z);\n      const p2 = proj(toNode.x, toNode.y, toNode.z);\n\n      robotState.x = p1.x + (p2.x - p1.x) * robotState.moveProgress;\n      robotState.y = p1.y + (p2.y - p1.y) * robotState.moveProgress;\n      robotState.z = fromNode.z + (toNode.z - fromNode.z) * robotState.moveProgress;\n\n      if (robotState.moveProgress >= 1) {\n        robotState.currentNodeId = robotState.targetNodeId;\n        robotState.targetNodeId = null;\n        robotState.isMoving = false;\n        robotState.moveProgress = 0;\n\n        const station = currentLevelData.foodStations.find(s => s.nodeId === robotState.currentNodeId);\n        if (station) {\n          robotState.carryingFood = station.food;\n          playSound('pickup');\n          updateCarryingHUD();\n        }\n\n        const customer = currentLevelData.customers.find(c => c.nodeId === robotState.currentNodeId && !c.delivered);\n        if (customer && robotState.carryingFood) {\n          if (customer.wantsFood.name === robotState.carryingFood.name) {\n            customer.delivered = true;\n            robotState.carryingFood = null;\n            deliveredCount++;\n            playSound('deliver');\n            updateHUD();\n            updateCarryingHUD();\n\n            if (deliveredCount >= totalCustomers) {\n              setTimeout(gameWin, 400);\n            }\n          }\n        }\n      }\n    }\n\n    /* ==========================================================================\n       RENDERING \u2014 PLATFORM POLYGON CONTINUOUS\n       ========================================================================== */\n\n    // Proyeksikan satu titik world ke screen\n    function P(x, y, z) {\n      return proj(x, y, z);\n    }\n\n    // Gambar polygon dengan outline tipis gelap\n    function fillPoly(pts, fill) {\n      ctx.beginPath();\n      ctx.moveTo(pts[0].x, pts[0].y);\n      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);\n      ctx.closePath();\n      ctx.fillStyle = fill;\n      ctx.fill();\n      ctx.strokeStyle = '#1e293b';\n      ctx.lineWidth = 1.3 * scaleFactor;\n      ctx.stroke();\n    }\n\n    // Test titik (x,y) world di dalam polygon pts\n    function pointInPoly(pts, x, y) {\n      let inside = false;\n      for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {\n        const xi = pts[i][0], yi = pts[i][1];\n        const xj = pts[j][0], yj = pts[j][1];\n        if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) {\n          inside = !inside;\n        }\n      }\n      return inside;\n    }\n\n    // Cari z tertinggi platform yang mengandung titik (x,y)\n    function maxZAt(x, y) {\n      let mz = 0;\n      for (const pl of MAZE_PLATFORMS) {\n        if (pl.z > mz && pointInPoly(pl.pts, x, y)) mz = pl.z;\n      }\n      return mz;\n    }\n\n    // Cari z tertinggi platform di bawah titik (x,y)\n    function maxZAt(x, y, ignorePlat) {\n      let mz = 0;\n      for (const pl of MAZE_PLATFORMS) {\n        if (pl === ignorePlat) continue;\n        if (pl.z < ignorePlat.z && pl.z > mz && pointInPoly(pl.pts, x, y)) {\n          mz = pl.z;\n        }\n      }\n      return mz;\n    }\n\n    // Gambar platform Arsitektural Sleek 3D (Lantai Putih + Step Riser Lavender Soft)\n    function drawPlatform(plat) {\n      const pts = plat.pts.map(([x, y]) => P(x, y, plat.z));\n      const n = pts.length;\n\n      let cx = 0, cy = 0;\n      pts.forEach(p => { cx += p.x; cy += p.y; });\n      cx /= n; cy /= n;\n\n      // Bayangan lembut di bawah platform\n      ctx.save();\n      ctx.fillStyle = 'rgba(15, 23, 42, 0.12)';\n      ctx.beginPath();\n      ctx.ellipse(cx, cy + (plat.z * 4 + 8) * scaleFactor, Math.max(Math.abs(pts[0].x - cx) * 1.3, 24), 9 * scaleFactor, 0, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.restore();\n\n      // Sisi kedalaman 3D step riser (ekstensi ke bawah presisi)\n      const edges = [];\n      const riserHeight = Math.min(plat.z, 1.25) * 16 * scaleFactor;\n\n      for (let i = 0; i < n; i++) {\n        const nextIdx = (i + 1) % n;\n        const wAx = plat.pts[i][0], wAy = plat.pts[i][1];\n        const wBx = plat.pts[nextIdx][0], wBy = plat.pts[nextIdx][1];\n\n        const a = pts[i];\n        const b = pts[nextIdx];\n\n        const mx = (wAx + wBx) / 2, my = (wAy + wBy) / 2;\n        const gcx = plat.pts.reduce((s, p) => s + p[0], 0) / n;\n        const gcy = plat.pts.reduce((s, p) => s + p[1], 0) / n;\n        let nx = mx - gcx, ny = my - gcy;\n        const nl = Math.hypot(nx, ny) || 1;\n        nx /= nl; ny /= nl;\n\n        const px = mx + nx * 0.15, py = my + ny * 0.15;\n        const zBelow = maxZAt(px, py, plat);\n\n        if (plat.z > zBelow && plat.z > 0) {\n          const isFront = (ny >= 0);\n          const shade = isFront ? '#c7d2fe' : '#a5b4fc';\n\n          edges.push({\n            isFront,\n            draw: () => {\n              ctx.beginPath();\n              ctx.moveTo(a.x, a.y);\n              ctx.lineTo(b.x, b.y);\n              ctx.lineTo(b.x, b.y + riserHeight);\n              ctx.lineTo(a.x, a.y + riserHeight);\n              ctx.closePath();\n              ctx.fillStyle = shade;\n              ctx.fill();\n              ctx.strokeStyle = '#000000';\n              ctx.lineWidth = 1.4 * scaleFactor;\n              ctx.stroke();\n            }\n          });\n        }\n      }\n\n      edges.filter(e => !e.isFront).forEach(e => e.draw());\n      edges.filter(e => e.isFront).forEach(e => e.draw());\n\n      // Permukaan Walkway Putih Bersih di Atas\n      ctx.beginPath();\n      ctx.moveTo(pts[0].x, pts[0].y);\n      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);\n      ctx.closePath();\n      ctx.fillStyle = '#ffffff';\n      ctx.fill();\n      ctx.strokeStyle = '#000000';\n      ctx.lineWidth = 2 * scaleFactor;\n      ctx.stroke();\n    }\n\n    // Tangga Arsitektural Putih + Garis Hitam\n    function drawStairs() {\n      if (!currentLevelData) return;\n      const items = [];\n      MAZE_STAIRS.forEach(st => {\n        const n = st.n;\n        const dx = (st.x2 - st.x1) / n;\n        const dy = (st.y2 - st.y1) / n;\n        const dz = (st.z2 - st.z1) / n;\n        for (let i = 0; i < n; i++) {\n          const x = st.x1 + dx * i;\n          const y = st.y1 + dy * i;\n          const z = st.z1 + dz * i;\n          const x2 = st.x1 + dx * (i + 1);\n          const y2 = st.y1 + dy * (i + 1);\n          const z2 = st.z1 + dz * (i + 1);\n          const a = P(x, y, z);\n          const b = P(x2, y2, z2);\n          const rise = (z2 - z) * HEIGHT_STEP * scaleFactor;\n          const vx = b.x - a.x;\n          const vy = b.y - a.y;\n          const len = Math.hypot(vx, vy) || 1;\n          const nx = -vy / len * 6 * scaleFactor;\n          const ny = vx / len * 6 * scaleFactor;\n          const depth = 7 * scaleFactor;\n          items.push({ d: (x + y) * 1000 + z, draw: () => {\n            // Riser depan lavender\n            ctx.beginPath();\n            ctx.moveTo(a.x, a.y);\n            ctx.lineTo(b.x, b.y);\n            ctx.lineTo(b.x, b.y - rise);\n            ctx.lineTo(a.x, a.y - rise);\n            ctx.closePath();\n            ctx.fillStyle = '#9db0f5';\n            ctx.fill();\n            ctx.strokeStyle = '#000000';\n            ctx.lineWidth = 1.2 * scaleFactor;\n            ctx.stroke();\n\n            // Anak tangga putih\n            ctx.beginPath();\n            ctx.moveTo(a.x + nx, a.y + ny - rise);\n            ctx.lineTo(b.x + nx, b.y + ny - rise);\n            ctx.lineTo(b.x + nx - depth, b.y + ny - depth - rise);\n            ctx.lineTo(a.x + nx - depth, a.y + ny - depth - rise);\n            ctx.closePath();\n            ctx.fillStyle = '#ffffff';\n            ctx.fill();\n            ctx.strokeStyle = '#000000';\n            ctx.lineWidth = 1.2 * scaleFactor;\n            ctx.stroke();\n          }});\n        }\n      });\n      items.sort((a, b) => a.d - b.d);\n      items.forEach(it => it.draw());\n    }\n\n    // Jembatan Lengkung Arsitektural Biru/Indigo\n    function drawBridges() {\n      MAZE_BRIDGES.forEach(b => {\n        const p1 = P(b.x1, b.y1, b.z);\n        const p2 = P(b.x2, b.y2, b.z);\n        const mx = (p1.x + p2.x) / 2;\n        const my = (p1.y + p2.y) / 2;\n        const dist = Math.hypot(p2.x - p1.x, p2.y - p1.y);\n        const arch = Math.max(12, dist * 0.5) * scaleFactor;\n\n        // Lengkungan bagian dalam (biru/indigo gelap)\n        ctx.strokeStyle = '#4338ca';\n        ctx.lineWidth = 5 * scaleFactor;\n        ctx.lineCap = 'round';\n        ctx.beginPath();\n        ctx.moveTo(p1.x, p1.y + 3 * scaleFactor);\n        ctx.quadraticCurveTo(mx, my + arch * 0.6, p2.x, p2.y + 3 * scaleFactor);\n        ctx.stroke();\n\n        // Jembatan atas putih\n        ctx.strokeStyle = '#ffffff';\n        ctx.lineWidth = 4 * scaleFactor;\n        ctx.beginPath();\n        ctx.moveTo(p1.x, p1.y);\n        ctx.quadraticCurveTo(mx, my - arch, p2.x, p2.y);\n        ctx.stroke();\n\n        // Outline subtle black line-art\n        ctx.strokeStyle = '#000000';\n        ctx.lineWidth = 1.3 * scaleFactor;\n        ctx.beginPath();\n        ctx.moveTo(p1.x, p1.y);\n        ctx.quadraticCurveTo(mx, my - arch, p2.x, p2.y);\n        ctx.stroke();\n\n        ctx.lineCap = 'butt';\n      });\n    }\n\n    // Taman: patch rumput hijau + pohon-pohon arsitektural\n    function drawGardens() {\n      MAZE_GARDENS.forEach(g => {\n        const p = P(g.x, g.y, g.z);\n        const w = g.w * UNIT_X * scaleFactor;\n        const h = g.h * UNIT_Y * scaleFactor;\n\n        ctx.beginPath();\n        ctx.moveTo(p.x - w / 2, p.y - h / 2);\n        ctx.lineTo(p.x, p.y - h / 2 + h / 2);\n        ctx.lineTo(p.x + w / 2, p.y);\n        ctx.lineTo(p.x, p.y + h / 2);\n        ctx.closePath();\n        ctx.fillStyle = '#48bb78';\n        ctx.fill();\n        ctx.strokeStyle = '#000000';\n        ctx.lineWidth = 1.5 * scaleFactor;\n        ctx.stroke();\n\n        const spots = [\n          { dx: -0.3, dy: -0.15 }, { dx: 0.25, dy: 0.15 },\n          { dx: 0.0, dy: 0.25 }, { dx: -0.1, dy: -0.35 }, { dx: 0.3, dy: -0.25 }\n        ];\n        for (let i = 0; i < g.n && i < spots.length; i++) {\n          const tx = p.x + spots[i].dx * w;\n          const ty = p.y + spots[i].dy * h;\n          drawTree(tx, ty);\n        }\n      });\n    }\n\n    function drawTree(tx, ty) {\n      const s = scaleFactor;\n      ctx.fillStyle = '#78350f';\n      ctx.fillRect(tx - 1.5 * s, ty - 7 * s, 3 * s, 7 * s);\n\n      ctx.fillStyle = '#22c55e';\n      ctx.beginPath();\n      ctx.arc(tx - 2.5 * s, ty - 10 * s, 4.5 * s, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.beginPath();\n      ctx.arc(tx + 2.5 * s, ty - 10 * s, 4.5 * s, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.fillStyle = '#4ade80';\n      ctx.beginPath();\n      ctx.arc(tx, ty - 14 * s, 5 * s, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.strokeStyle = '#000000';\n      ctx.lineWidth = 1.2 * s;\n      ctx.stroke();\n    }\n\n    function drawMiniCharacter(cx, cy, s) {\n      ctx.fillStyle = 'rgba(0,0,0,0.3)';\n      ctx.beginPath();\n      ctx.ellipse(cx, cy + 2 * s, 4.5 * s, 2 * s, 0, 0, Math.PI * 2);\n      ctx.fill();\n\n      ctx.fillStyle = '#ffffff';\n      ctx.strokeStyle = '#000000';\n      ctx.lineWidth = 1.5 * s;\n      ctx.beginPath();\n      ctx.arc(cx, cy - 11 * s, 3.8 * s, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.stroke();\n      ctx.beginPath();\n      (ctx.roundRect ? ctx.roundRect : function(x,y,w,h,r){ctx.rect(x,y,w,h);}).call(ctx, cx - 3.8 * s, cy - 7 * s, 7.6 * s, 6.5 * s, 2.2 * s);\n      ctx.fill();\n      ctx.stroke();\n    }\n\n    function drawCollectible(c) {\n      const p = P(c.x, c.y, c.z);\n      const floatY = Math.sin(Date.now() * 0.004 + c.x + c.y) * 3 * scaleFactor;\n      const s = scaleFactor;\n      const x = p.x;\n      const y = p.y - 16 * s + floatY;\n\n      ctx.fillStyle = 'rgba(0,0,0,0.2)';\n      ctx.beginPath();\n      ctx.ellipse(p.x, p.y + 2 * s, 5.5 * s, 2.4 * s, 0, 0, Math.PI * 2);\n      ctx.fill();\n\n      ctx.fillStyle = '#ef4444';\n      ctx.strokeStyle = '#000000';\n      ctx.lineWidth = 1.4 * s;\n      ctx.beginPath();\n      (ctx.roundRect ? ctx.roundRect : function(x,y,w,h,r){ctx.rect(x,y,w,h);}).call(ctx, x - 5 * s, y - 5 * s, 10 * s, 9.5 * s, 2.5 * s);\n      ctx.fill();\n      ctx.stroke();\n\n      ctx.fillStyle = '#fef08a';\n      ctx.fillRect(x - 1.3 * s, y - 5 * s, 2.6 * s, 9.5 * s);\n      ctx.fillRect(x - 5 * s, y - 1.6 * s, 10 * s, 3.2 * s);\n    }\n\n    // Model Obstacle 3D Kualitas Tinggi (Pedestrian Sweeper / Traffic Cone)\n    function draw3DObstacleModel(x, y, obs) {\n      ctx.save();\n      const s = scaleFactor;\n      const walkBob = Math.abs(Math.sin(Date.now() * 0.012 + obs.t * 10)) * 4 * s;\n\n      // Bayangan Karakter / Obstacle\n      ctx.fillStyle = 'rgba(0,0,0,0.35)';\n      ctx.beginPath();\n      ctx.ellipse(x, y + 2 * s, 8 * s, 3.5 * s, 0, 0, Math.PI * 2);\n      ctx.fill();\n\n      if (obs.icon && (obs.icon.includes('\ud83d\udea7') || obs.icon.includes('\ud83d\uded1'))) {\n        ctx.fillStyle = '#f97316';\n        ctx.beginPath();\n        ctx.moveTo(x - 8 * s, y);\n        ctx.lineTo(x + 8 * s, y);\n        ctx.lineTo(x + 4 * s, y - 20 * s);\n        ctx.lineTo(x - 4 * s, y - 20 * s);\n        ctx.closePath();\n        ctx.fill();\n        ctx.strokeStyle = '#000000';\n        ctx.lineWidth = 1.5 * s;\n        ctx.stroke();\n\n        ctx.fillStyle = '#ffffff';\n        ctx.fillRect(x - 5 * s, y - 14 * s, 10 * s, 4 * s);\n\n        const flash = Math.sin(Date.now() * 0.015) > 0;\n        ctx.fillStyle = flash ? '#ef4444' : '#fee2e2';\n        ctx.beginPath();\n        ctx.arc(x, y - 22 * s, 3.5 * s, 0, Math.PI * 2);\n        ctx.fill();\n      } else {\n        ctx.fillStyle = '#0f172a';\n        ctx.fillRect(x - 5 * s, y - 2 * s - walkBob, 3.2 * s, 4.5 * s);\n        ctx.fillRect(x + 2 * s, y - 2 * s + walkBob, 3.2 * s, 4.5 * s);\n\n        ctx.fillStyle = '#ef4444';\n        ctx.beginPath();\n        (ctx.roundRect ? ctx.roundRect : function(x,y,w,h,r){ctx.rect(x,y,w,h);}).call(ctx, x - 7 * s, y - 18 * s - walkBob, 14 * s, 14 * s, 4);\n        ctx.fill();\n        ctx.strokeStyle = '#000000';\n        ctx.lineWidth = 1.5 * s;\n        ctx.stroke();\n\n        ctx.fillStyle = '#fef08a';\n        ctx.fillRect(x - 7 * s, y - 12 * s - walkBob, 14 * s, 3 * s);\n\n        ctx.fillStyle = '#facc15';\n        ctx.beginPath();\n        ctx.arc(x, y - 23 * s - walkBob, 5.5 * s, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.strokeStyle = '#000000';\n        ctx.lineWidth = 1.3 * s;\n        ctx.stroke();\n\n        ctx.fillStyle = '#0f172a';\n        ctx.fillRect(x - 3 * s, y - 24 * s - walkBob, 6 * s, 2.5 * s);\n      }\n      ctx.restore();\n    }\n\n    /* ==========================================================================\n       RENDER GAME \u2014 PAINTER'S ALGORITHM\n       ========================================================================== */\n    function renderGame() {\n      try {\n        _renderGameInternal();\n      } catch(e) {\n        console.error(\"Error in renderGame:\", e);\n      }\n    }\n\n        // Cute Robot Player Model (Cyan & Gold Futuristic Delivery Bot)\n    function drawRobotPlayerModel(rx, ry) {\n      ctx.save();\n      const s = scaleFactor || 1.0;\n      const hoverBob = Math.sin(Date.now() * 0.008) * 3 * s;\n      const x = rx;\n      const y = ry + hoverBob;\n\n      // Robot Shadow\n      ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';\n      ctx.beginPath();\n      try { ctx.ellipse(rx, ry + 4 * s, 10 * s, 4.5 * s, 0, 0, Math.PI * 2); } catch(e) {}\n      ctx.fill();\n\n      // Robot Body (Cyan/Sky Blue Futuristic Capsule)\n      ctx.fillStyle = '#0284c7';\n      ctx.beginPath();\n      (ctx.roundRect ? ctx.roundRect : function(x,y,w,h,r){ctx.rect(x,y,w,h);}).call(ctx, x - 9 * s, y - 24 * s, 18 * s, 22 * s, 6 * s);\n      ctx.fill();\n      ctx.strokeStyle = '#000000';\n      ctx.lineWidth = 1.8 * s;\n      ctx.stroke();\n\n      // Screen Face / Visor (Dark Blue)\n      ctx.fillStyle = '#0f172a';\n      ctx.beginPath();\n      (ctx.roundRect ? ctx.roundRect : function(x,y,w,h,r){ctx.rect(x,y,w,h);}).call(ctx, x - 7 * s, y - 20 * s, 14 * s, 10 * s, 3 * s);\n      ctx.fill();\n\n      // Glowing Cyan Eyes\n      ctx.fillStyle = '#38bdf8';\n      ctx.beginPath();\n      ctx.arc(x - 3.5 * s, y - 15 * s, 2 * s, 0, Math.PI * 2);\n      ctx.arc(x + 3.5 * s, y - 15 * s, 2 * s, 0, Math.PI * 2);\n      ctx.fill();\n\n      // Antenna\n      ctx.strokeStyle = '#0284c7';\n      ctx.lineWidth = 2 * s;\n      ctx.beginPath();\n      ctx.moveTo(x, y - 24 * s);\n      ctx.lineTo(x, y - 29 * s);\n      ctx.stroke();\n      ctx.fillStyle = '#f59e0b';\n      ctx.beginPath();\n      ctx.arc(x, y - 30 * s, 2.5 * s, 0, Math.PI * 2);\n      ctx.fill();\n\n      // Carrying Food Icon Bubble\n      if (robotState && robotState.carryingFood) {\n        ctx.font = `${Math.round(18 * s)}px sans-serif`;\n        ctx.textAlign = 'center';\n        ctx.fillText(robotState.carryingFood.icon, x, y - 34 * s);\n      }\n\n      ctx.restore();\n    }\n\n    function _renderGameInternal() {\n      // Sky Horizon Background (Matching reference image diagonal split)\n      const skyGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);\n      skyGrad.addColorStop(0, '#ffffff');\n      skyGrad.addColorStop(0.65, '#f0f9ff');\n      skyGrad.addColorStop(1, '#e0f2fe');\n      ctx.fillStyle = skyGrad;\n      ctx.fillRect(0, 0, canvas.width, canvas.height);\n\n      // Diagonal Sky Blue Horizon Cut at Bottom\n      ctx.fillStyle = '#7dd3fc';\n      ctx.beginPath();\n      ctx.moveTo(0, canvas.height * 0.78);\n      ctx.lineTo(canvas.width, canvas.height * 0.68);\n      ctx.lineTo(canvas.width, canvas.height);\n      ctx.lineTo(0, canvas.height);\n      ctx.closePath();\n      ctx.fill();\n\n      // RENDER MAP BACKGROUND IMAGE (maps_robo-delivery2.png) ALWAYS\n      const b = getMapBounds();\n      if (mapBgImg) {\n        ctx.save();\n        try {\n          ctx.drawImage(mapBgImg, b.dx, b.dy, b.dw, b.dh);\n        } catch(e) {}\n        ctx.restore();\n      }\n\n      if (!currentLevelData) return;\n\n      // 7. Track Jalur Node (Clean & Minimalist - Only connected paths near Robot)\n      currentLevelData.edges.forEach(edge => {\n        const n1 = currentLevelData.nodes.find(n => n.id === edge[0]);\n        const n2 = currentLevelData.nodes.find(n => n.id === edge[1]);\n        const isCurrentEdge = (robotState.currentNodeId === n1.id || robotState.currentNodeId === n2.id);\n\n        if (isCurrentEdge) {\n          const p1 = P(n1.x, n1.y, n1.z);\n          const p2 = P(n2.x, n2.y, n2.z);\n\n          ctx.strokeStyle = 'rgba(56, 189, 248, 0.6)';\n          ctx.lineWidth = 3.5 * scaleFactor;\n          ctx.setLineDash([6 * scaleFactor, 4 * scaleFactor]);\n          ctx.beginPath();\n          ctx.moveTo(p1.x, p1.y);\n          ctx.lineTo(p2.x, p2.y);\n          ctx.stroke();\n          ctx.setLineDash([]);\n\n          const pulseT = ((Date.now() * 0.0025) % 1);\n          const px = p1.x + (p2.x - p1.x) * pulseT;\n          const py = p1.y + (p2.y - p1.y) * pulseT;\n          ctx.fillStyle = '#f59e0b';\n          ctx.beginPath();\n          ctx.arc(px, py, 3.5 * scaleFactor, 0, Math.PI * 2);\n          ctx.fill();\n        }\n      });\n\n      // 8. Waypoint Nodes Presisi\n      currentLevelData.nodes.forEach(node => {\n        const p = P(node.x, node.y, node.z);\n        const isCurrent = (robotState.currentNodeId === node.id);\n        const isConnected = isEdgeConnected(robotState.currentNodeId, node.id);\n        const isHovered = (hoveredNodeId === node.id);\n\n        ctx.save();\n        if (isHovered || isConnected) {\n          const pulse = Math.sin(Date.now() * 0.008 + node.id) * 2 * scaleFactor;\n          ctx.fillStyle = isHovered ? 'rgba(250, 204, 21, 0.4)' : 'rgba(56, 189, 248, 0.3)';\n          ctx.beginPath();\n          ctx.arc(p.x, p.y, (12 * scaleFactor) + pulse, 0, Math.PI * 2);\n          ctx.fill();\n        }\n\n        ctx.beginPath();\n        ctx.arc(p.x, p.y, (isHovered ? 10 : isConnected ? 8 : 6) * scaleFactor, 0, Math.PI * 2);\n\n        if (isCurrent) {\n          ctx.fillStyle = '#38bdf8';\n          ctx.strokeStyle = '#000000';\n          ctx.lineWidth = 2 * scaleFactor;\n        } else if (isHovered) {\n          ctx.fillStyle = '#facc15';\n          ctx.strokeStyle = '#000000';\n          ctx.lineWidth = 2 * scaleFactor;\n        } else if (isConnected) {\n          ctx.fillStyle = '#ffffff';\n          ctx.strokeStyle = '#000000';\n          ctx.lineWidth = 1.8 * scaleFactor;\n        } else {\n          ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';\n          ctx.strokeStyle = '#64748b';\n          ctx.lineWidth = 1.2 * scaleFactor;\n        }\n        ctx.fill();\n        ctx.stroke();\n\n        if (isHovered) {\n          ctx.fillStyle = '#facc15';\n          ctx.beginPath();\n          ctx.moveTo(p.x, p.y - 18 * scaleFactor);\n          ctx.lineTo(p.x - 5 * scaleFactor, p.y - 25 * scaleFactor);\n          ctx.lineTo(p.x + 5 * scaleFactor, p.y - 25 * scaleFactor);\n          ctx.closePath();\n          ctx.fill();\n          ctx.strokeStyle = '#000000';\n          ctx.lineWidth = 1 * scaleFactor;\n          ctx.stroke();\n        }\n\n        ctx.restore();\n      });\n\n      // 9. Food stations\n      currentLevelData.foodStations.forEach(station => {\n        const node = currentLevelData.nodes.find(n => n.id === station.nodeId);\n        const p = P(node.x, node.y, node.z);\n        const floatY = Math.sin(Date.now() * 0.005 + node.id) * 3 * scaleFactor;\n\n        ctx.font = `${Math.round(22 * scaleFactor)}px sans-serif`;\n        ctx.textAlign = 'center';\n        ctx.fillText(station.food.icon, p.x, p.y - 12 * scaleFactor + floatY);\n      });\n\n      // 10. Customers\n      currentLevelData.customers.forEach(customer => {\n        const node = currentLevelData.nodes.find(n => n.id === customer.nodeId);\n        const p = P(node.x, node.y, node.z);\n\n        if (customer.delivered) {\n          ctx.font = `${Math.round(22 * scaleFactor)}px sans-serif`;\n          ctx.textAlign = 'center';\n          ctx.fillText('\ud83d\ude03\u2764\ufe0f', p.x, p.y - 10 * scaleFactor);\n        } else {\n          const charIcon = customer.gender === 'female' ? '\ud83d\udc69' : '\ud83d\udc68';\n          ctx.font = `${Math.round(24 * scaleFactor)}px sans-serif`;\n          ctx.textAlign = 'center';\n          ctx.fillText(charIcon, p.x, p.y - 9 * scaleFactor);\n          drawThoughtBubble(p.x + 14 * scaleFactor, p.y - 34 * scaleFactor, customer.wantsFood.icon);\n        }\n      });\n\n      // 11. Obstacles (Dashed Danger Trail + Pulsing Red Ring)\n      currentLevelData.obstacles.forEach(obs => {\n        const fromN = currentLevelData.nodes.find(n => n.id === obs.path[obs.currentIndex]);\n        const toN = currentLevelData.nodes.find(n => n.id === obs.path[obs.targetIndex]);\n        const p1 = P(fromN.x, fromN.y, fromN.z);\n        const p2 = P(toN.x, toN.y, toN.z);\n        const ox = p1.x + (p2.x - p1.x) * obs.t;\n        const oy = p1.y + (p2.y - p1.y) * obs.t;\n\n        ctx.save();\n        ctx.strokeStyle = 'rgba(239, 68, 68, 0.4)';\n        ctx.lineWidth = 2.5 * scaleFactor;\n        ctx.setLineDash([4 * scaleFactor, 4 * scaleFactor]);\n        ctx.beginPath();\n        ctx.moveTo(p1.x, p1.y);\n        ctx.lineTo(p2.x, p2.y);\n        ctx.stroke();\n        ctx.restore();\n\n        ctx.save();\n        const sf = Math.max(0.2, scaleFactor || 1.0);\n        const hazardPulse = Math.sin(Date.now() * 0.01) * 2 * sf;\n        const rx = Math.max(4, (14 * sf) + hazardPulse);\n        const ry = Math.max(2, rx * 0.55);\n        \n        ctx.fillStyle = 'rgba(239, 68, 68, 0.22)';\n        ctx.beginPath();\n        try { ctx.ellipse(ox, oy + 3 * sf, rx, ry, 0, 0, Math.PI * 2); } catch(e) {}\n        ctx.fill();\n\n        ctx.strokeStyle = '#ef4444';\n        ctx.lineWidth = 1.5 * sf;\n        ctx.beginPath();\n        try { ctx.ellipse(ox, oy + 3 * sf, rx, ry, 0, 0, Math.PI * 2); } catch(e) {}\n        ctx.stroke();\n        ctx.restore();\n\n        draw3DObstacleModel(ox, oy, obs);\n      });\n\n      // 12. Player robot (Map Aligned Movement)\n      const fromNode = currentLevelData.nodes.find(n => n.id === robotState.currentNodeId);\n      const toNode = (robotState.targetNodeId !== null && robotState.targetNodeId !== undefined) ? currentLevelData.nodes.find(n => n.id === robotState.targetNodeId) : fromNode;\n\n      let currX = fromNode ? fromNode.x : 20.5;\n      let currY = fromNode ? fromNode.y : 22;\n\n      if (robotState.isMoving && fromNode && toNode) {\n        currX = fromNode.x + (toNode.x - fromNode.x) * robotState.moveProgress;\n        currY = fromNode.y + (toNode.y - fromNode.y) * robotState.moveProgress;\n      }\n\n      const rp = P(currX, currY);\n      drawRobotPlayerModel(rp.x, rp.y);\n\n      // 13. Animasi Tabrakan (Bump)\n      if (robotState.bumpAnim > 0) {\n        robotState.bumpAnim--;\n        ctx.font = `bold 22px sans-serif`;\n        ctx.fillStyle = '#ef4444';\n        ctx.textAlign = 'center';\n        ctx.fillText('\ud83d\udca5 BUMP!', robotState.x, robotState.y - 44 * scaleFactor);\n      }\n    }\n\n    function drawThoughtBubble(x, y, icon) {\n      ctx.save();\n      ctx.fillStyle = '#ffffff';\n      ctx.strokeStyle = '#0f172a';\n      ctx.lineWidth = 1.8 * scaleFactor;\n\n      ctx.beginPath();\n      ctx.arc(x, y, 13 * scaleFactor, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.stroke();\n\n      ctx.beginPath();\n      ctx.arc(x - 8 * scaleFactor, y + 11 * scaleFactor, 3.2 * scaleFactor, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.stroke();\n\n      ctx.font = `${Math.round(13 * scaleFactor)}px sans-serif`;\n      ctx.textAlign = 'center';\n      ctx.textBaseline = 'middle';\n      ctx.fillText(icon, x, y);\n      ctx.restore();\n    }\n\n    function drawRobotPlayer(x, y, z) {\n      ctx.save();\n      const floatHover = Math.sin(Date.now() * 0.008) * 3 * scaleFactor;\n      const s = scaleFactor;\n\n      // Bayangan Robot\n      ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';\n      ctx.beginPath();\n      ctx.ellipse(x, y + 2 * s, 14 * s, 6 * s, 0, 0, Math.PI * 2);\n      ctx.fill();\n\n      // Thruster Glow di bawah robot\n      const glowGrad = ctx.createRadialGradient(x, y - 4 * s + floatHover, 1 * s, x, y - 4 * s + floatHover, 10 * s);\n      glowGrad.addColorStop(0, 'rgba(56, 189, 248, 0.8)');\n      glowGrad.addColorStop(1, 'rgba(56, 189, 248, 0)');\n      ctx.fillStyle = glowGrad;\n      ctx.beginPath();\n      ctx.ellipse(x, y - 4 * s + floatHover, 10 * s, 5 * s, 0, 0, Math.PI * 2);\n      ctx.fill();\n\n      // Badan Gradient Metalik 3D\n      const bodyGrad = ctx.createLinearGradient(x - 12 * s, y - 35 * s, x + 12 * s, y - 10 * s);\n      bodyGrad.addColorStop(0, '#38bdf8');\n      bodyGrad.addColorStop(0.5, '#0284c7');\n      bodyGrad.addColorStop(1, '#0369a1');\n\n      // Kepala Robot\n      ctx.fillStyle = bodyGrad;\n      ctx.strokeStyle = '#0f172a';\n      ctx.lineWidth = 2 * s;\n      ctx.beginPath();\n      (ctx.roundRect ? ctx.roundRect : function(x,y,w,h,r){ctx.rect(x,y,w,h);}).call(ctx, x - 11 * s, y - 35 * s + floatHover, 22 * s, 16 * s, 6);\n      ctx.fill();\n      ctx.stroke();\n\n      // Visor Layar Cyan\n      ctx.fillStyle = '#0f172a';\n      ctx.beginPath();\n      (ctx.roundRect ? ctx.roundRect : function(x,y,w,h,r){ctx.rect(x,y,w,h);}).call(ctx, x - 8 * s, y - 32 * s + floatHover, 16 * s, 9 * s, 3);\n      ctx.fill();\n\n      // Mata LED Visor\n      ctx.fillStyle = '#38bdf8';\n      ctx.beginPath();\n      ctx.arc(x - 4 * s, y - 27.5 * s + floatHover, 2.5 * s, 0, Math.PI * 2);\n      ctx.arc(x + 4 * s, y - 27.5 * s + floatHover, 2.5 * s, 0, Math.PI * 2);\n      ctx.fill();\n\n      // Badan Robot\n      ctx.fillStyle = '#f8fafc';\n      ctx.strokeStyle = '#0f172a';\n      ctx.lineWidth = 2 * s;\n      ctx.beginPath();\n      (ctx.roundRect ? ctx.roundRect : function(x,y,w,h,r){ctx.rect(x,y,w,h);}).call(ctx, x - 9.5 * s, y - 17 * s + floatHover, 19 * s, 14 * s, 5);\n      ctx.fill();\n      ctx.stroke();\n\n      // Core Badge Dada\n      ctx.fillStyle = '#38bdf8';\n      ctx.beginPath();\n      ctx.arc(x, y - 10 * s + floatHover, 3 * s, 0, Math.PI * 2);\n      ctx.fill();\n\n      // Antena Lampu Beacon\n      ctx.strokeStyle = '#0f172a';\n      ctx.lineWidth = 1.5 * s;\n      ctx.beginPath();\n      ctx.moveTo(x, y - 35 * s + floatHover);\n      ctx.lineTo(x, y - 42 * s + floatHover);\n      ctx.stroke();\n      ctx.fillStyle = '#facc15';\n      ctx.beginPath();\n      ctx.arc(x, y - 44 * s + floatHover, 2.8 * s, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.stroke();\n\n      // Tas/Box Pengantar saat membawa makanan\n      if (robotState.carryingFood) {\n        ctx.fillStyle = '#f97316';\n        ctx.strokeStyle = '#7c2d12';\n        ctx.lineWidth = 1.5 * s;\n        ctx.beginPath();\n        (ctx.roundRect ? ctx.roundRect : function(x,y,w,h,r){ctx.rect(x,y,w,h);}).call(ctx, x + 9 * s, y - 24 * s + floatHover, 12 * s, 12 * s, 3);\n        ctx.fill();\n        ctx.stroke();\n\n        ctx.font = `${Math.round(10 * s)}px sans-serif`;\n        ctx.textAlign = 'center';\n        ctx.textBaseline = 'middle';\n        ctx.fillText(robotState.carryingFood.icon, x + 15 * s, y - 18 * s + floatHover);\n      }\n\n      ctx.restore();\n    }\n\n    /* ==========================================================================\n       POINTER & TOUCH INTERACTION\n       ========================================================================== */\n    function handlePointer(clientX, clientY) {\n      if (!isGameRunning || !currentLevelData) return;\n\n      const rect = canvas.getBoundingClientRect();\n      const clickX = clientX - rect.left;\n      const clickY = clientY - rect.top;\n\n      let foundHoverNode = null;\n      currentLevelData.nodes.forEach(node => {\n        const p = P(node.x, node.y, node.z);\n        const dist = Math.hypot(clickX - p.x, clickY - p.y);\n        if (dist <= 20 * scaleFactor) {\n          foundHoverNode = node.id;\n        }\n      });\n\n      hoveredNodeId = foundHoverNode;\n      return foundHoverNode;\n    }\n\n    canvas.addEventListener('mousemove', (e) => {\n      handlePointer(e.clientX, e.clientY);\n    });\n\n    canvas.addEventListener('click', (e) => {\n      const clickedId = handlePointer(e.clientX, e.clientY);\n      if (clickedId !== null && clickedId !== undefined) {\n        moveToNode(clickedId);\n      }\n    });\n\n    canvas.addEventListener('touchstart', (e) => {\n      if (e.touches.length > 0) {\n        const touch = e.touches[0];\n        const clickedId = handlePointer(touch.clientX, touch.clientY);\n        if (clickedId !== null && clickedId !== undefined) {\n          moveToNode(clickedId);\n        }\n      }\n    });\n\n    /* ==========================================================================\n       MAIN LOOP\n       ========================================================================== */\n    function gameLoop() {\n      updateRobot();\n      updateObstacles();\n      checkObstacleCollisions();\n      renderGame();\n      requestAnimationFrame(gameLoop);\n    }\n\n    resizeCanvas();\n    loadLevel(0);\n    requestAnimationFrame(gameLoop);\n\n  ";

